/**
 * 设置页：左侧分类、右侧内容，方便后续持续增加开关。
 *
 * 当前只有「自动化推进」和「独立评审」；保存后写入本机 profile，
 * 不写仓库、不影响其他开发者。
 */
import { useEffect, useState } from 'react'
import { h } from './i18n.mjs'
import { API } from '../shared/api.mjs'
import { normalizeAutomation } from '../shared/automation.mjs'
import { SkillsPanel } from './skills.mjs'
import { Button, IconSeat, Pill, T, api, errorText, styles } from './common.mjs'

function EngineIcon({ id }) {
  if (id === 'dsh') {
    return h(IconSeat, { size: 28, tone: 'accent' }, '✦')
  }
  if (id === 'claude') {
    return h('svg', { width: 28, height: 28, viewBox: '0 0 28 28', 'aria-hidden': true },
      h('circle', { cx: 14, cy: 14, r: 13, fill: '#f5e9e2' }),
      h('path', { fill: 'none', stroke: '#d97757', strokeWidth: 2.2, strokeLinecap: 'round', d: 'M14 4v7M14 17v7M4 14h7M17 14h7M6.9 6.9l5 5M16.1 16.1l5 5M6.9 21.1l5-5M16.1 11.9l5-5' }))
  }
  if (id === 'codex') {
    return h('svg', { width: 28, height: 28, viewBox: '0 0 28 28', 'aria-hidden': true },
      h('rect', { x: 2, y: 2, width: 24, height: 24, rx: 7, fill: '#111827' }),
      h('text', { x: 14, y: 19, textAnchor: 'middle', fill: '#fff', fontFamily: 'Menlo, monospace', fontSize: 13, fontWeight: 700 }, '>_'))
  }
  return h('svg', { width: 28, height: 28, viewBox: '0 0 28 28', 'aria-hidden': true },
    h('rect', { x: 2, y: 2, width: 24, height: 24, rx: 7, fill: '#e8f1ff' }),
    h('text', { x: 14, y: 20, textAnchor: 'middle', fill: '#2563eb', fontFamily: 'Georgia, serif', fontSize: 18, fontWeight: 700 }, 'π'))
}

function OptionCard({ active, title, hint, icon = null, onSelect, disabled = false }) {
  return h('button', {
    type: 'button',
    disabled,
    onClick: disabled ? undefined : onSelect,
    style: {
      textAlign: 'left',
      display: 'flex',
      flexDirection: 'column',
      gap: 6,
      padding: '14px 16px',
      height: '100%',
      border: `1px solid ${active ? T.brand : T.borderSoft}`,
      borderRadius: T.rLg,
      background: active ? T.brandSoft : T.surface,
      color: T.text,
      cursor: disabled ? 'not-allowed' : 'pointer',
      opacity: disabled ? 0.55 : 1,
      fontFamily: 'inherit',
      boxShadow: active ? `0 0 0 2px rgba(96,73,231,.10)` : T.shadowCard,
    },
  },
    h('div', { style: { display: 'flex', alignItems: 'center', gap: 9 } },
      icon ? h('span', { style: { flex: '0 0 auto', display: 'inline-flex' } }, icon) : null,
      h('span', { style: { fontSize: T.font.base, fontWeight: 650, minWidth: 0 } }, title),
      active ? h(Pill, { tone: 'accent' }, '当前') : null),
    h('div', { style: { ...styles.sectionHint, lineHeight: 1.65 } }, hint),
  )
}

function SettingRow({ title, hint, children }) {
  return h('div', { style: { ...styles.card, padding: '14px 16px' } },
    h('div', { style: { display: 'flex', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' } },
      h('div', { style: { display: 'flex', flexDirection: 'column', gap: 4, flex: '1 1 420px', minWidth: 0 } },
        h('span', { style: { fontSize: T.font.base, fontWeight: 600, color: T.text } }, title),
        h('span', { style: { ...styles.sectionHint, lineHeight: 1.7 } }, hint)),
      h('div', { style: { flex: '0 0 auto' } }, children)),
  )
}

function NavButton({ active, children, onClick, disabled = false }) {
  return h('button', {
    type: 'button',
    onClick,
    style: {
      width: '100%',
      textAlign: 'left',
      padding: '9px 10px',
      border: 'none',
      borderRadius: T.rBase,
      background: active ? T.brandSoft : 'transparent',
      color: active ? T.brand : T.text2,
      cursor: disabled ? 'not-allowed' : 'pointer',
      opacity: disabled ? 0.55 : 1,
      fontFamily: 'inherit',
      fontSize: T.font.sm,
      fontWeight: active ? 600 : 500,
    },
  }, children)
}

export function AutomationSettings({ initialSection = 'automation' } = {}) {
  const [automation, setAutomation] = useState(() => normalizeAutomation(null))
  const [repo, setRepo] = useState(null)
  const [dshAvailable, setDshAvailable] = useState(!globalThis.__DEVHUB_STANDALONE__)
  const [claudeAvailable, setClaudeAvailable] = useState(false)
  const [codexAvailable, setCodexAvailable] = useState(false)
  const [piAvailable, setPiAvailable] = useState(false)
  const [section, setSection] = useState(initialSection === 'skills' ? 'skills' : 'automation')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [notice, setNotice] = useState('')
  const [loadError, setLoadError] = useState('')
  const [saveError, setSaveError] = useState('')

  useEffect(() => {
    let alive = true
    api(API.settings)
      .then((body) => { if (alive) { setAutomation(normalizeAutomation(body?.automation)); setRepo(body?.repo ?? null); setDshAvailable(body?.dshAvailable !== false); setClaudeAvailable(Boolean(body?.claudeAvailable)); setCodexAvailable(Boolean(body?.codexAvailable)); setPiAvailable(Boolean(body?.piAvailable)) } })
      .catch((err) => { if (alive) setLoadError(errorText(err)) })
      .finally(() => { if (alive) setLoading(false) })
    return () => { alive = false }
  }, [])

  async function save(next = automation) {
    setSaving(true); setSaveError(''); setNotice('')
    try {
      const body = await api(API.settings, { method: 'POST', body: JSON.stringify({ automation: next }) })
      const previous = normalizeAutomation(automation)
      const nextValue = normalizeAutomation(body?.automation ?? next)
      setAutomation(nextValue)
      const engineChanged = nextValue.engine !== previous.engine
      const modeChanged = nextValue.mode !== previous.mode || nextValue.reviewEnabled !== previous.reviewEnabled
      const permissionChanged = nextValue.claudePermissionMode !== previous.claudePermissionMode
      const engineLabel = { dsh: 'DSH 原生会话', claude: 'Claude Code', codex: 'Codex', pi: 'Pi' }[nextValue.engine] ?? nextValue.engine
      const baseNotice = permissionChanged && !modeChanged && !engineChanged
        ? '已保存 Claude Code 开发权限模式'
        : engineChanged && !modeChanged
          ? `已切换 AI 引擎：${engineLabel}（开发、澄清、评审都会使用它）`
        : nextValue.mode === 'full'
          ? (nextValue.reviewEnabled === false
            ? '已保存：完全自动化 + 已关闭独立评审，流程直接进入测试验证'
            : '已保存：评审、本机自测、环境测试会自动推进，停在提交前')
          : '已保存：每个节点都需要你手动触发'
      const warnings = Array.isArray(body?.warnings) ? body.warnings : []
      setNotice(warnings.length ? `${baseNotice}；部分流程未更新：${warnings.slice(0, 3).join('；')}` : baseNotice)
    } catch (err) {
      setSaveError(errorText(err))
    } finally { setSaving(false) }
  }

  const sections = [
    { id: 'automation', label: '自动化推进' },
    { id: 'review', label: '独立评审' },
    { id: 'engine', label: '开发引擎' },
    { id: 'skills', label: '技能' },
  ]
  const current = sections.find((entry) => entry.id === section) ?? sections[0]

  return h('div', {
    style: {
      display: 'grid',
      gridTemplateColumns: 'minmax(150px, 190px) minmax(0, 1fr)',
      gap: T.gap.md,
      alignItems: 'start',
      padding: '16px 18px',
      maxWidth: 1180,
    },
  },
    h('aside', {
      style: {
        display: 'flex',
        flexDirection: 'column',
        gap: 4,
        position: 'sticky',
        top: 12,
      },
    },
      h('div', { style: { ...styles.sectionTitle, padding: '0 10px 6px' } }, '设置'),
      sections.map((entry) => h(NavButton, {
        key: entry.id,
        active: section === entry.id,
        onClick: () => setSection(entry.id),
      }, entry.label)),
    ),
    h('main', { style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 } },
      h('div', { style: { display: 'flex', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' } },
        h('div', { style: { display: 'flex', flexDirection: 'column', gap: 3, flex: '1 1 360px' } },
          h('div', { style: { fontSize: T.font.md, fontWeight: 650, color: T.text } }, current.label),
          h('div', { style: styles.sectionHint },
            current.id === 'automation'
              ? `控制当前项目（${repo?.name ?? '当前项目'}）的推进动作；提交与推送始终由你确认。`
              : current.id === 'engine'
                ? `选择当前项目（${repo?.name ?? '当前项目'}）由谁执行开发、澄清和评审。`
                : current.id === 'skills'
                  ? `管理当前项目（${repo?.name ?? '当前项目'}）的技能包与约束。`
                  : '控制是否引入独立评审，以及按规模选择评审强度。')),
        current.id === 'skills' || current.id === 'engine'
          ? null
          : h(Button, { primary: true, disabled: loading || saving, onClick: () => save(), children: saving ? '保存中…' : '保存设置' }),
      ),
      loadError ? h('div', { style: styles.dangerCard }, `读取设置失败：${loadError}`) : null,
      saveError ? h('div', { style: styles.dangerCard }, `保存失败：${saveError}`) : null,
      notice ? h('div', { style: styles.infoCard }, notice) : null,

      section === 'engine'
        ? h('div', { style: { display: 'flex', flexDirection: 'column', gap: 10 } },
          h('div', { style: { ...styles.card, padding: '16px 18px', display: 'flex', flexDirection: 'column', gap: 8 } },
            h('div', { style: { fontSize: T.font.md, fontWeight: 650, color: T.text } }, 'AI 引擎（开发 / 澄清 / 评审）'),
            h('div', { style: styles.sectionHint },
              '决定开发、需求澄清和独立评审由谁执行。切换只影响之后的调用；已有流程的代码与历史不变。'),
            h('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 10 } },
              dshAvailable ? h(OptionCard, {
                icon: h(EngineIcon, { id: 'dsh' }),
                title: 'DSH 原生会话',
                hint: '用 DSH 原生会话执行开发、澄清和评审；自动化与纠偏衔接最完整。',
                active: automation.engine === 'dsh',
                onSelect: () => save({ ...automation, engine: 'dsh' }),
              }) : null,
              h(OptionCard, {
                icon: h(EngineIcon, { id: 'claude' }),
                title: 'Claude Code',
                hint: claudeAvailable
                  ? '用本机 Claude Code 执行开发、澄清和评审；开发会话可在工作站查看日志或打开终端。'
                  : '未检测到 claude 命令：请先安装 Claude Code CLI 并登录。',
                active: automation.engine === 'claude',
                disabled: !claudeAvailable || saving,
                onSelect: () => { if (claudeAvailable) save({ ...automation, engine: 'claude' }) },
              }),
              h(OptionCard, {
                icon: h(EngineIcon, { id: 'codex' }),
                title: 'Codex',
                hint: codexAvailable
                  ? '用本机 Codex CLI 执行澄清和评审；开发阶段在终端中进行，可用 bridge CLI 回写台账。'
                  : '未检测到 codex 命令：请先安装 Codex CLI 并登录。',
                active: automation.engine === 'codex',
                disabled: !codexAvailable || saving,
                onSelect: () => { if (codexAvailable) save({ ...automation, engine: 'codex' }) },
              }),
              h(OptionCard, {
                icon: h(EngineIcon, { id: 'pi' }),
                title: 'Pi',
                hint: piAvailable
                  ? '用本机 Pi CLI 执行澄清和评审；开发阶段在终端中进行，可用 bridge CLI 回写台账。'
                  : '未检测到 pi 命令：请先安装 Pi CLI 并登录。',
                active: automation.engine === 'pi',
                disabled: !piAvailable || saving,
                onSelect: () => { if (piAvailable) save({ ...automation, engine: 'pi' }) },
              }),
            ),
            automation.engine === 'claude'
              ? h('div', { style: { ...styles.card, padding: '12px 14px', display: 'flex', flexDirection: 'column', gap: 6 } },
                h('span', { style: { fontSize: T.font.base, fontWeight: 600, color: T.text } }, 'Claude Code 开发权限'),
                h('span', { style: styles.sectionHint },
                  'auto 会自动处理常见的命令权限请求，推荐；acceptEdits 会在需要命令行权限时停下，需去终端处理；bypassPermissions 会放行所有工具，需先在终端接受免责声明，风险更高。'),
                h('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap' } },
                  ...['auto', 'acceptEdits', 'bypassPermissions'].map((mode) => h(Button, {
                    key: mode,
                    style: automation.claudePermissionMode === mode ? { borderColor: T.brand, background: T.brandSoft, color: T.brand } : {},
                    onClick: () => save({ ...automation, claudePermissionMode: mode }),
                    children: mode === 'auto' ? 'auto（推荐）' : mode === 'acceptEdits' ? 'acceptEdits' : 'bypassPermissions（高风险）',
                  })),
                ),
              )
              : null,
            !claudeAvailable
              ? h('div', { style: styles.sectionHint }, '安装参考：macOS/Linux 用 curl -fsSL https://claude.ai/install.sh | bash；Windows 用 irm https://claude.ai/install.ps1 | iex；安装后确认 claude --version 可用')
              : null,
          ))
        : section === 'skills'
        ? h('div', { style: { display: 'flex', flexDirection: 'column', gap: 10 } },
          h(SkillsPanel))
        : section === 'automation'
        ? h('div', { style: { display: 'flex', flexDirection: 'column', gap: 10 } },
          loading
            ? h('div', { style: { ...styles.sectionHint, padding: '10px 2px' } }, '正在读取设置…')
            : h('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 10 } },
              h(OptionCard, {
                active: automation.mode === 'full',
                title: '完全自动化（默认）',
                hint: '开发任务完成 → 自动开始评审；评审通过 → 自动跑本机自测 → 自动跑环境测试；到「待提交」停下。',
                onSelect: () => setAutomation((currentValue) => ({ ...currentValue, mode: 'full' })),
              }),
              h(OptionCard, {
                active: automation.mode === 'manual',
                title: '人工触发每个节点',
                hint: '评审、本机自测、环境测试都由你点按钮触发；工作站只提示下一步。',
                onSelect: () => setAutomation((currentValue) => ({ ...currentValue, mode: 'manual' })),
              })),
          h('div', { style: styles.infoCard },
            automation.mode === 'full'
              ? '当前：自动开始评审、自动跑本机自测和环境测试，停在提交前；评审未通过仍会退回开发，不会自动改代码。'
              : '当前：每个节点都停下来等你点；工作站只给出下一步提示。'),
          h('div', { style: { ...styles.sectionHint, lineHeight: 1.7 } },
            '自动化在流程详情打开并读取到状态时生效；开发会话还在跑时不会抢跑。提交/推送始终手动确认。'),
        )
        : h('div', { style: { display: 'flex', flexDirection: 'column', gap: 10 } },
          h(SettingRow, {
            title: '启用独立评审环节',
            hint: '开启时按工程量决定评审强度（S 免评审，M 1 位，L/XL 2 位）；关闭后所有流程跳过独立评审，直接进入测试验证。已经失败的评审仍会保留，不会替你忽略。',
            children: h('input', {
              type: 'checkbox',
              checked: automation.reviewEnabled !== false,
              disabled: loading,
              onChange: (event) => setAutomation((currentValue) => ({ ...currentValue, reviewEnabled: event.target.checked })),
              style: { width: 18, height: 18, marginTop: 2, cursor: loading ? 'default' : 'pointer' },
            }),
          }),
          h('div', { style: styles.infoCard },
            automation.reviewEnabled === false
              ? '当前：独立评审已关闭；开发完成后直接进入测试验证。'
              : '当前：独立评审已开启；小改动仍会按规模自动免评审，中大改动保留评审。'),
        ),
    ),
  )
}
